p=Path('labyrinth/seed.py');s=p.read_text(encoding='utf8').replace('dict(id="new-presentations", group=G1','dict(id="new-presentations", updated=DAY, group=G1');s=s.replace('T1  LIT. Classical results are published. The three 2026 papers are unrefereed preprints; the brief of this\n      run files them as literature, and each such node says so in its status.','T1  Peer-reviewed literature or standard facts. LIT identifies provenance, not tier.\n      Supplied 2026 preprint claims are conservatively T2 with explicit review status.');p.write_text(s,encoding='utf8')
fixes=[('02-dual-and-two-trees.md','The equality is the reason states exist in step 03.','The equality is necessary for a state to be a bijection. It does not alone prove that an incidence matching exists; step 03 supplies the matching argument.'),('02-dual-and-two-trees.md','its faces, listed counterclockwise, are','its coherently oriented face boundaries are listed below. Bounded faces run counterclockwise in the chosen drawing; the outer boundary has the opposite planar orientation. The faces are'),('05-cancellation.md','The twins must have equal weight. Only functions of $s$ are allowed.','The twins must have equal weight. A function of $s$ guarantees this. More general weights are possible if they are invariant under the chosen involution.'),('08-gluing-and-hypotheses.md',"Tutte's theory allows any three roots of three different colours. Lead G2 in the same file conjectures that a suitable triple always admits a pair. Untested, and the recovery of step 07 would need a replacement for the three spokes of $t_0$.","Lead G2 proposes roots of three different colours away from one face, but does not specify which black face to omit. Without that omission there are k black faces and k-1 nonroot vertices, so a bijection is impossible by counting. A corrected formulation and a replacement for the three outer spokes are needed before testing it.")]
for f,a,b in fixes:
 p=Path('digestions/steps')/f;s=p.read_text(encoding='utf8');assert a in s;p.write_text(s.replace(a,b),encoding='utf8')
